  const progress = el('div', { role: 'status', class: 'flow-note', 'aria-live': 'polite' }); const errors = el('div', { class: 'validation-errors', hidden: '', role: 'alert', tabindex: '-1' });
  m.content.append(el('div', { class: 'review-content' }, field('HTML plan or research report', html, 'Standard manifests import directly. Other reports open a guided repair screen.'), field('Accompanying images & videos', media, 'Use the filenames referenced in the HTML. You can resolve missing files in the next step.'), progress, errors));
